// doc: sum(s) returns the sum of all integers in sequence s.
// Returns 0 for the empty sequence. Raises OverflowError in Python on very large sums,
// but we treat this as unbounded integer arithmetic.
// synth:
function sum(s: seq<int>): int {
  // synth:
  if s == [] then 0 else s[0] + sum(s[1..])
// synth:
}

// synth: helper function to extract odd values at even indices for the comprehension
function oddAtEvenIndices(lst: seq<int>, idx: int := 0): seq<int>
  // synth:
  requires idx <= |lst|
  // synth:
  decreases |lst| - idx
// synth:
{
  // synth:
  if idx >= |lst| then []
  // synth:
  else if idx % 2 == 0 && lst[idx] % 2 == 1 then
    // synth:
    [lst[idx]] + oddAtEvenIndices(lst, idx + 1)
  // synth:
  else
    // synth:
    oddAtEvenIndices(lst, idx + 1)
// synth:
}

