// doc: range(n) returns a sequence [0, 1, ..., n-1] of integers when n >= 0.
// If n <= 0, it returns an empty sequence.
function range(n: int): seq<int> {
  if n <= 0 then [] else range(n-1) + [n-1]
}

// doc: lst.append(x) modifies lst by adding element x to the end.
// Returns a new sequence with x appended.
function append<T>(lst: seq<T>, x: T): seq<T> {
  lst + [x]
}

// doc: lst.pop() removes and returns the last element of lst.
// Requires lst to be non-empty; raises IndexError if empty.
// Returns the last element; the list is modified to remove it.
function pop<T>(lst: seq<T>): T
  requires |lst| > 0
{
  lst[|lst| - 1]
}

// doc: lst.pop(0) removes and returns the first element of lst.
// Requires lst to be non-empty; raises IndexError if empty.
// Returns the first element; the list is modified to remove it.
function popFront<T>(lst: seq<T>): T
  requires |lst| > 0
{
  lst[0]
}

// doc: Returns the list without the first element.
// Requires lst to be non-empty.
function removeFront<T>(lst: seq<T>): seq<T>
  requires |lst| > 0
{
  lst[1..]
}

// doc: Returns the list without the last element.
// Requires lst to be non-empty.
function removeBack<T>(lst: seq<T>): seq<T>
  requires |lst| > 0
{
  lst[..|lst| - 1]
}

// synth: Max helper function for non-empty integer sequences
function Max(s: seq<int>): int
  requires |s| > 0
  decreases |s|
{
  if |s| == 1 then s[0]
  else if Max(s[..|s|-1]) >= s[|s|-1] then Max(s[..|s|-1]) else s[|s|-1]
}

// src: source.py:3 | def rolling_max(numbers: List[int]) -> List[int]:
method rolling_max(numbers: seq<int>) returns (result: seq<int>)
  ensures |result| == |numbers| && (forall i :: 0 <= i < |numbers| ==> result[i] >= Max(numbers[0..i+1]))
{
  // src: source.py:4 | rolling_max_list = []
  var rolling_max_list: seq<int> := [];
  // src: source.py:5 | max_indices = []
  var max_indices: seq<int> := [];
  // src: source.py:6 | for i in range(len(numbers)):
  for i := 0 to |numbers|
  {
    // src: source.py:7 | if len(max_indices) > 0 and max_indices[0] <= i - len(rolling_max_list):
    if |max_indices| > 0 && max_indices[0] <= i - |rolling_max_list|
    {
      // src: source.py:8 | max_indices.pop(0)
      max_indices := removeFront(max_indices);
    }
    // src: source.py:9 | while len(max_indices) > 0 and numbers[i] >= numbers[max_indices[-1]]:
    while |max_indices| > 0 && numbers[i] >= numbers[max_indices[|max_indices| - 1]]
    {
      // src: source.py:10 | max_indices.pop()
      max_indices := removeBack(max_indices);
    }
    // src: source.py:11 | max_indices.append(i)
    max_indices := append(max_indices, i);
    // src: source.py:12 | rolling_max_list.append(numbers[max_indices[0]])
    rolling_max_list := append(rolling_max_list, numbers[max_indices[0]]);
  }
  // src: source.py:13 | return rolling_max_list
  result := rolling_max_list;
}

