method pairs_sum_to_zero(l: seq<int>) returns (result: bool)
  ensures !result || exists i, j :: 0 <= i < |l| && 0 <= j < |l| && i != j && l[i] + l[j] == 0
{
  // src: source.py:2 | if len(l) < 2:
  if |l| < 2 {
    // src: source.py:3 | return False
    result := false;
    return;
  }
  // src: source.py:4 | elements_set = set(l)
  var elements_set := SetFromSeq(l);
  // src: source.py:5 | for elem in l:
  for i := 0 to |l| {
    var elem := l[i];
    // src: source.py:6 | if -elem in elements_set:
    if -elem in elements_set {
      // src: source.py:7 | return True
      result := true;
      return;
    }
  }
  // src: source.py:8 | return False
  result := false;
  return;
}

