// src: source.py:3 | def string_xor(a: str, b: str) -> str:
method string_xor(a: string, b: string) returns (result: string)
  requires forall i :: 0 <= i < |a| ==> a[i] in ['0', '1']
  requires forall i :: 0 <= i < |b| ==> b[i] in ['0', '1']
  ensures |result| == |a| && |a| == |b| && forall i :: 0 <= i < |result| ==> result[i] in ['0', '1']
{
  // src: source.py:4 | result = int(a, 2) ^ int(b, 2)
  var xor_result := IntXor(BinaryStringToInt(a), BinaryStringToInt(b));
  // src: source.py:5 | return bin(result)[2:]
  result := IntToBinaryString(xor_result);
}
